import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import toast, { Toaster } from "react-hot-toast";

const Roadmap = () => {
  const [progress, setProgress] = useState(0);

  // Load progress from localStorage on component mount
  useEffect(() => {
    const savedProgress = localStorage.getItem("roadmapProgress");
    if (savedProgress) {
      setProgress(parseInt(savedProgress));
    }
  }, []);

  // Save progress to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem("roadmapProgress", progress);
  }, [progress]);

  const handleLessonClick = (index) => {
    if (index === progress) {
      toast.success(`Navigating to Lesson ${index + 1}`);
      setProgress((prev) => prev + 1); // Advance progress
    } else if (index < progress) {
      toast("You’ve already completed this lesson!");
    } else {
      toast.error("Complete previous lessons first!");
    }
  };

  return (
    <div className="roadmap-container">
      <Toaster />
      <div className="roadmap">
        {[...Array(5)].map((_, index) => (
          <div
            key={index}
            className={`lesson-circle ${index <= progress ? "completed" : ""}`}
            onClick={() => handleLessonClick(index)}
            aria-label={`Lesson ${index + 1}`}
            role="button"
            tabIndex={0}
          >
            {index + 1}
          </div>
        ))}
        <motion.div
          className="avatar"
          animate={{ x: progress * 100 }} // Adjust based on your layout
          transition={{ type: "spring", stiffness: 100 }}
        >
          🎓
        </motion.div>
      </div>
    </div>
  );
};

export default Roadmap;
